using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------- configuration ----------
var openAiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var searchKey   = Environment.GetEnvironmentVariable("BRAVE_API_KEY"); // optional
var modelId     = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var topic       = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Research Agent — topic: \"{topic}\"\n");

// ---------- tool implementations ----------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query, searchKey),
        "web_search",
        "Search the web for information. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Concise note to save")] string note) =>
        {
            notebook.Add(note);
            return $"Saved note #{notebook.Count}.";
        },
        "save_note",
        "Save an important finding to the notebook for later summarization."),

    AIFunctionFactory.Create(
        () => notebook.All(),
        "read_notes",
        "Read all notes saved so far.")
};

// ---------- chat client with tools ----------
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Given a topic you must:
        1. Search the web 2-3 times with varied queries to gather broad information.
        2. Save each key finding as a note using save_note.
        3. After gathering enough information, read your notes and produce a
           well-structured summary with sections and references.
        Be thorough but concise.
        """),
    new(ChatRole.User, $"Research this topic: {topic}")
};

// ---------- agent loop ----------
const int maxTurns = 15;
for (var turn = 0; turn < maxTurns; turn++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);

    // Append all response messages to the conversation
    foreach (var msg in response.Messages)
        messages.Add(msg);

    // Check if the model invoked any tools this turn
    bool usedTools = response.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

    if (!usedTools)
    {
        // Final answer — print it
        var answer = response.Messages
            .LastOrDefault(m => m.Role == ChatRole.Assistant && m.Text is not null);
        Console.WriteLine("═══ Research Summary ═══\n");
        Console.WriteLine(answer?.Text ?? "(no summary produced)");
        break;
    }

    // Show progress
    var calls = response.Messages.SelectMany(m => m.Contents.OfType<FunctionCallContent>());
    foreach (var fc in calls)
        Console.WriteLine($"  ⚙ {fc.Name}({Truncate(fc.Arguments)})");
}

Console.WriteLine($"\n📝 {notebook.Count} notes collected during research.");

// ---------- helpers ----------
static string Truncate(IReadOnlyDictionary<string, object?>? args, int max = 80)
{
    if (args is null) return "";
    var s = string.Join(", ", args.Select(kv => $"{kv.Key}={kv.Value}"));
    return s.Length <= max ? s : s[..max] + "…";
}

// ---------- Notebook ----------
sealed class Notebook
{
    private readonly List<string> _notes = [];
    public void Add(string note) => _notes.Add(note);
    public int Count => _notes.Count;
    public string All() => _notes.Count == 0
        ? "(no notes yet)"
        : string.Join('\n', _notes.Select((n, i) => $"{i + 1}. {n}"));
}

// ---------- Web search tool ----------
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query, string? braveApiKey)
    {
        if (!string.IsNullOrWhiteSpace(braveApiKey))
            return await BraveSearchAsync(query, braveApiKey);

        // Fallback: use DuckDuckGo instant-answer API (no key required)
        return await DdgSearchAsync(query);
    }

    private static async Task<string> BraveSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5";
        using var req = new HttpRequestMessage(HttpMethod.Get, url);
        req.Headers.Add("Accept", "application/json");
        req.Headers.Add("X-Subscription-Token", apiKey);

        var resp = await Http.SendAsync(req);
        resp.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
        var results = doc.RootElement
            .GetProperty("web").GetProperty("results")
            .EnumerateArray()
            .Take(5)
            .Select(r => $"- {r.GetProperty("title").GetString()}: " +
                         $"{r.GetProperty("description").GetString()} " +
                         $"({r.GetProperty("url").GetString()})");

        return string.Join('\n', results);
    }

    private static async Task<string> DdgSearchAsync(string query)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var resp = await Http.GetAsync(url);
        resp.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
        var parts = new List<string>();

        var abs = doc.RootElement.GetProperty("Abstract").GetString();
        if (!string.IsNullOrWhiteSpace(abs))
            parts.Add($"Summary: {abs}");

        foreach (var topic in doc.RootElement.GetProperty("RelatedTopics").EnumerateArray().Take(5))
        {
            if (topic.TryGetProperty("Text", out var text))
                parts.Add($"- {text.GetString()}");
        }

        return parts.Count > 0
            ? string.Join('\n', parts)
            : "No results found. Try a different query.";
    }
}

